void jr(ostream&o,const R&r){o<<"{\"numerator\":";jp(o,r.n);o<<",\"denominator\":";jp(o,r.d);o<<'}';}
P unitproduct;
bool unit_numerator(const R&r){if(zero(r))return false;P p=r.n;for(int step=0;step<100;step++){P g;fmpq_poly_gcd(g.v,p.v,unitproduct.v);if(fmpq_poly_degree(g.v)==0)break;p=quotient(p,g);}return fmpq_poly_degree(p.v)==0;}
// Fixed finite source-cofactor construction, no Gaussian search. Helpers prepended.
using V=vector<R>;
V va(const V&a,const V&b){assert(a.size()==b.size());V c=a;for(size_t i=0;i<c.size();i++)c[i]=add(c[i],b[i]);return c;}
V vs(const V&a,const R&s){V b=a;for(auto&x:b)x=mul(x,s);return b;}
V evalrow(const V&cof,const vector<V>&rows){V v(rows[0].size());for(size_t i=0;i<rows.size();i++)if(!zero(cof[i]))for(size_t j=0;j<v.size();j++)v[j]=add(v[j],mul(cof[i],rows[i][j]));return v;}
R readr(istream&f){auto readp=[&](){long n;f>>n;P p;fmpq_t q;fmpq_init(q);for(long i=0;i<n;i++){long k;string s;f>>k>>s;assert(!fmpq_set_str(q,s.c_str(),10));fmpq_canonicalise(q);fmpq_poly_set_coeff_fmpq(p.v,k,q);}fmpq_clear(q);return p;};P n=readp(),d=readp();return R(n,d);}
